def _pp_iterated_module(for_node: ast.For, pp_modules: set[str]) -> tuple[str, str] | None:
    """
    If ``for_node`` iterates over a PP-managed submodule accessed on ``self`` (optionally wrapped in
    ``enumerate``/``reversed``), return ``(loop_variable_name, self_reference)``. Otherwise return ``None``.
    """
    iter_node = for_node.iter
    if (
        isinstance(iter_node, ast.Call)
        and isinstance(iter_node.func, ast.Name)
        and iter_node.func.id in {"enumerate", "reversed", "list", "tuple"}
        and iter_node.args
    ):
        iter_node = iter_node.args[0]

    self_ref = _self_attribute_chain(iter_node)
    if self_ref is None:
        return None
    if self_ref[len("self.") :] not in pp_modules:
        return None

    target = for_node.target
    if isinstance(target, ast.Name):
        loop_var = target.id
    elif isinstance(target, ast.Tuple):
        # e.g. `for idx, layer in enumerate(self.layers)`: the iterated module is the last element.
        name_targets = [element.id for element in target.elts if isinstance(element, ast.Name)]
        loop_var = name_targets[-1] if name_targets else None
    else:
        loop_var = None

    if loop_var is None:
        return None
    return loop_var, self_ref


def trf011_check_pp_unsafe_attribute_access(
    tree: ast.Module, file_path: Path, source_lines: list[str], violations: list[Violation], rule_id: str
