    pp_plan_by_model = _PP_PLAN_MODULES_BY_MODEL_DIR
    if not pp_plan_by_model:
        return violations

    model_dir = _model_dir_name(file_path)
    if model_dir is None:
        return violations

    pp_modules = pp_plan_by_model.get(model_dir)
    if not pp_modules:
        return violations

    class_to_bases = _collect_class_bases(tree)
    for node in tree.body:
        if not isinstance(node, ast.ClassDef):
            continue
        if not _inherits_pretrained_model(node.name, class_to_bases):
            continue

        forward_method = _class_methods(node).get("forward")
        if forward_method is None:
            continue

        # 1) Attribute accesses on loop variables that iterate over a PP-managed submodule.
        for for_node in (sub for sub in ast.walk(forward_method) if isinstance(sub, ast.For)):
            iterated = _pp_iterated_module(for_node, pp_modules)
            if iterated is None:
                continue
            loop_var, self_ref = iterated
            for sub_node in ast.walk(for_node):
                if not (
                    isinstance(sub_node, ast.Attribute)
                    and isinstance(sub_node.value, ast.Name)
                    and sub_node.value.id == loop_var
                ):
                    continue
                if sub_node.attr in _STANDARD_NN_MODULE_ATTRS:
                    continue
                if _has_rule_suppression(source_lines, rule_id, sub_node.lineno):
                    continue
                access_expr = full_name(sub_node)
                violations.append(
                    Violation(
                        file_path=file_path,
                        line_number=sub_node.lineno,
                        rule_id=rule_id,
                        message=(
                            f"{rule_id}: unsafe attribute access `{access_expr}` on `{self_ref}`, which is managed "
                            "by the pipeline parallelism plan and may not be materialized on the current rank. "
                            "Call the submodule instead of reaching into its attributes."
                        ),
                    )
                )

        # 2) Direct `self.<pp_module>.<attr>` accesses.
        for sub_node in ast.walk(forward_method):
            if not isinstance(sub_node, ast.Attribute):
                continue
            base_chain = _self_attribute_chain(sub_node.value)
            if base_chain is None:
                continue
            pp_module = base_chain[len("self.") :]
            if pp_module not in pp_modules:
                continue
            if sub_node.attr in _STANDARD_NN_MODULE_ATTRS:
                continue
            if _has_rule_suppression(source_lines, rule_id, sub_node.lineno):
                continue
            access_chain = full_name(sub_node)
            violations.append(
                Violation(
                    file_path=file_path,
                    line_number=sub_node.lineno,
                    rule_id=rule_id,
                    message=(
                        f"{rule_id}: unsafe attribute access `{access_chain}` on a submodule managed by the "
                        "pipeline parallelism plan, which may not be materialized on the current rank. "
                        "Call the submodule instead of reaching into its attributes."
                    ),
                )
            )

    return violations


